fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    // If desired, ensure at runtime (in debug builds) that the inputs have the same length.
    debug_assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");
    
    // Zip the two vectors together, bitwise-and each pair, and collect into a new Vec<u8>
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a & b)
      .collect()
}

